        print("Michelangelo ...")

class Lithographer(ArtisticAIBase):
    def draw(self, output_file):
        print(f"Drawing with lithography technique in {output_file}")
        self.pem()
        self.stamp()

    def pem(self):
        print("Pemsieve ...")

    def stamp(self):
        print("Stamp ...")

