from datetime import datetime

def get_latest_folder(path):
    latest = None
    for root, dirs, files in os.walk(path):
        latest = max(latest, datetime.now(root)) if latest else None
        for d in dirs:
            latest = max(latest, datetime.now(os.path.join(root,d)))

    if latest is None:
        return None
    else:
        return os.path.join(root,latest)

def archive_folder(path):
    now = datetime.now().strftime("%Y-%m-%d")

    archive_name = os.path.join(path,f"backup_{now}")

    tar = tarfile.open(archive_name, "w")
    tar.add(path, arcname=os.path.basename(path))
    tar.close()

    return archive_name

def backup():
    entries = get_latest_folder("/var/www")
    if entries:
        archive_name = archive_folder(entries)
        os.remove(entries)
        os.rename(archive_name, entries)
    else:
        print("Backup not possible")

