import os
from pathlib import Path

def find_corrupted_files(dir_path):
    corrupted_files = []

    for root, dirs, files in os.walk(dir_path):
        for file in files:
            fpath = Path(root) / file
            if is_corrupted(fpath):
                corrupted_files.append(fpath)

    return corrupted_files

def is_corrupted(fpath):
    with open(fpath, 'rb') as f:
        data = f.read()
        if b'Corrupted' in data:
            return True

    return False

def delete_corrupted_files(corrupted_files):
    for fpath in corrupted_files:
        os.chmod(fpath, 0o777)
        os.remove(fpath)

