from zope.publisher import TraversalError

class AdapteeAdapter(grok.Adapter):
    def __call__(self):
        return self.identifier

    def __eq__(self, other):
        if not super().__eq__(other):
            return False
        if self.identifier != other.identifier:
            return False
        return True

def my_adaptee(adapter, identifier):
    router = getAdapter(adapter)
    for key, value in router.items():
        if key == identifier:
