from cereal import log
import shutil

def copy_romdata(input_dir, output_dir):
    for rom in os.listdir(input_dir):
        rom_dir = os.path.join(input_dir, rom)

        if log.rom_data.get(rom, []):

            for pad in log.rom_data[rom]:
                data_dir_base = os.path.join(output_dir, pad, 'rom_data')

                if not os.path.exists(data_dir_base):
                    os.mkdir(data_dir_base)

                for f in os.listdir(rom_dir):
                    fpath = os.path.join(rom_dir, f)
                    data_path = os.path.join(data_dir_base, f)

                    shutil.copy(fpath, data_path)

    log.rom_data.clear()
    os.rmdir(os.path.join(output_dir, 'rom_data'))


